using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class BeachJoinDeduplicate{static BeachJoinDeduplicate(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachJoinDeduplicate.request"))return;File.Delete("BeachJoinDeduplicate.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roads=s.GetRootGameObjects().Single(g=>g.name=="Track Roads");var joins=roads.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.ToLower().Contains("beach promenade sidewalk joins")).OrderBy(f=>PrefabUtility.IsAddedGameObjectOverride(f.gameObject)?1:0).ToArray();foreach(var f in joins.Skip(1))Object.DestroyImmediate(f.gameObject);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.AppendAllText("FinalEnvironmentRoadReview/BeachPromenadeJoin.txt","\nFinal scene duplicate join removed; one matching paving mesh/collider remains.");}}
